for rid, candidates in options.items():
 context, historic, walls, scope = rooms[rid]
 for letter, spec in candidates.items():
  dest = ROOT / f'rooms/{rid}/board/round-013/candidates/{letter}.md'
  lines = [f'# {rid} — Candidate {letter} — complete tile design option', '', DISCLAIMER, '',
           '## Room program, material identity and selected fixtures', '',
           f'**Shared room authority.** {context} {GEOM}; {PLUMB}. Two identical PH copies. Original quoted per-copy material-only {historic}; not an owner room cap or current bid. All 15%-inclusive source gross once: {scope}.', '',
           f'**Material design.** {spec["intro"]}', '',
           '## Source-specific wall, floor, drain and price control', '',
           '| Surface | Individual maker product / finish / application | Original per-copy gross or measured gap | Historical USD source vs actual alternate price | Exact test, cut, joint, edge and build gate |',
           '|---|---|---|---|---|']
  for r in spec['rows']:
   assert len(r)==5
   lines.append('| '+' | '.join(r)+' |')
  lines += ['', '## Drawing-derived dimensional and waterproofing study', '',
            f'**Nominal wall coordinates:** {walls}. All are provisional dimensions in {GEOM}. Verify real tile size/caliber, window and valve axes, exposed corners, movement joints, grout joint, sill/return waterproofing, edge profiles and drain location against a confirmed 1529 model. The existing wall-cut studies are not released installation elevations.', '',
            '**Execution and sample gate.** '+spec['depth'], '',
            '## Manufacturer evidence and separate release gates', '',
            '**Explicit individual gates:** '+spec['test'], '', COMMON, '',
            '## Cost/quantity, owner/GC decision and market bounds', '',
            f'**Source arithmetic.** Original {historic}/unit tile-only material source ×2 PH copies, preserving every gross 15% inclusion once; per-room installed quote, current actual order/carton quantities and alternate-vs-source dollar delta are **null**. Manufacturer carton figures where known are packaging facts only, not approved case orders. PH Primary WC is inherited in Primary floor, and a niche is excluded. Niche faces/back/returns cannot be double counted.', '',
            f'**Market discipline.** PH buyer target $2.8M, TX $2.7M, comparator $2.4M–$3.2M. {MKT} are listing-copy amenities, not certified images or evidence of specific competitor tile patterns; four 405 W Armitage records represent one building. Actual owner room/material allowance and sample signoff **null**.', '',
            f'**Required evidence before contract or PO.** Confirm manufacturer raw wet DCOF for each actual LEVEL/PAN SKU, exact wet-use finish and selected point/linear rough/waterproof assembly; obtain measured 1529 field plan, source-to-net takeoff with real carton coverage, owner-approved color/grout/edge and signed cost, current Chicago supplier stock/lead/freight and GC flood-test/shop drawings. {NEW} provides only the scoped multi-format desk evidence. No purchase or fixture substitution authorized.', '']
  dest.parent.mkdir(parents=True,exist_ok=True)
  expected='\n'.join(lines)
  if dest.exists():
   assert dest.read_text(encoding='utf-8') == expected, f'Refusing overwrite of an independently changed candidate: {dest}'
  else:
   dest.write_text(expected,encoding='utf-8')
  print(rid, letter, dest.stat().st_size)
